import React, {
  ForwardedRef,
  forwardRef,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react';
import {FlatList, Image, Text, View} from 'react-native';
import {Theme} from '../../types/interfaces';
import {RulesSection} from '../../lib/rules/types';
import styles from '../../styles/RulesScreenStyles';

interface RulesDocumentViewProps {
  sections: RulesSection[];
  query: string;
  theme: Theme;
  onAnchorNavigation?: (anchor: string) => void;
}

export interface RulesDocumentViewHandle {
  scrollToAnchor: (anchor: string) => void;
}

interface HighlightPart {
  text: string;
  highlighted: boolean;
}

interface HeadingRow {
  key: string;
  type: 'heading';
  anchor: string;
  text: string;
  pageRef: number;
}

interface ParagraphRow {
  key: string;
  type: 'paragraph';
  anchor: string;
  blockIndex: number;
  runs: Array<{text: string; href?: string}>;
}

interface ImageRow {
  key: string;
  type: 'image';
  anchor: string;
  imageUri: string;
  imageCaption?: string;
}

type DocRow = HeadingRow | ParagraphRow | ImageRow;

function splitHighlight(text: string, query: string): HighlightPart[] {
  const normalized = query.trim().toLowerCase();
  if (!normalized) {
    return [{text, highlighted: false}];
  }

  const sourceLower = text.toLowerCase();
  const parts: HighlightPart[] = [];
  let cursor = 0;

  while (cursor < text.length) {
    const hit = sourceLower.indexOf(normalized, cursor);
    if (hit === -1) {
      parts.push({text: text.slice(cursor), highlighted: false});
      break;
    }

    if (hit > cursor) {
      parts.push({text: text.slice(cursor, hit), highlighted: false});
    }

    parts.push({
      text: text.slice(hit, hit + normalized.length),
      highlighted: true,
    });
    cursor = hit + normalized.length;
  }

  return parts.filter(part => part.text.length > 0);
}

function isBulletLine(text: string): boolean {
  return /^\s*(?:[-*•]|\d+\.)\s+/.test(text);
}

const RulesDocumentView = forwardRef(
  (
    {sections, query, theme, onAnchorNavigation}: RulesDocumentViewProps,
    ref: ForwardedRef<RulesDocumentViewHandle>,
  ) => {
    const listRef = useRef<FlatList<DocRow>>(null);
    const anchorIndexRef = useRef<Record<string, number>>({});

    const normalizedQuery = useMemo(() => query.trim(), [query]);
    const rows = useMemo(() => {
      const output: DocRow[] = [];
      const anchorRowMap: Record<string, number> = {};

      sections.forEach(section => {
        const headingIndex = output.length;
        anchorRowMap[section.anchor] = headingIndex;
        output.push({
          key: `${section.anchor}-heading`,
          type: 'heading',
          anchor: section.anchor,
          text: section.title,
          pageRef: section.pageRef,
        });

        section.blocks
          .filter(block => block.type !== 'heading')
          .forEach((block, blockIndex) => {
            if (block.type === 'image' && block.image?.uri) {
              output.push({
                key: `${section.anchor}-image-${blockIndex}`,
                type: 'image',
                anchor: section.anchor,
                imageUri: block.image.uri,
                imageCaption: block.image.caption,
              });
              return;
            }

            output.push({
              key: `${section.anchor}-paragraph-${blockIndex}`,
              type: 'paragraph',
              anchor: section.anchor,
              blockIndex,
              runs: block.textRuns,
            });
          });
      });

      anchorIndexRef.current = anchorRowMap;
      return output;
    }, [sections]);

    const scrollToAnchor = (anchor: string) => {
      const index = anchorIndexRef.current[anchor];
      if (typeof index !== 'number') {
        return;
      }
      listRef.current?.scrollToIndex({
        index,
        animated: true,
        viewPosition: 0,
      });
    };

    useImperativeHandle(ref, () => ({
      scrollToAnchor,
    }));

    return (
      <FlatList
        testID="rules-document-scroll"
        ref={listRef}
        style={styles.contentContainer}
        contentContainerStyle={{
          ...styles.docContent,
          backgroundColor: theme.backgroundColor,
        }}
        data={rows}
        keyExtractor={item => item.key}
        initialNumToRender={40}
        maxToRenderPerBatch={32}
        updateCellsBatchingPeriod={60}
        windowSize={7}
        removeClippedSubviews={true}
        onScrollToIndexFailed={() => {}}
        renderItem={({item}) => {
          if (item.type === 'heading') {
            return (
              <View
                testID={`rules-section-${item.anchor}`}
                style={{
                  ...styles.sectionCard,
                  borderColor: theme.dividerColor,
                  backgroundColor: theme.translucentBackgroundColor,
                }}>
                <View style={styles.headingRow}>
                  <Text style={{...styles.pageBadge, color: theme.foregroundColor}}>
                    Page {item.pageRef}
                  </Text>
                </View>
                <Text style={{...styles.headingText, color: theme.foregroundColor}}>
                  {item.text}
                </Text>
              </View>
            );
          }

          if (item.type === 'image') {
            return (
              <View
                style={{
                  ...styles.imageBlock,
                  borderColor: theme.dividerColor,
                  backgroundColor: theme.translucentBackgroundColor,
                }}>
                <Image
                  source={{uri: item.imageUri}}
                  resizeMode="contain"
                  style={{
                    width: '100%',
                    height:
                      item.imageUri && item.imageUri.length > 0
                        ? 240
                        : 220,
                    backgroundColor: theme.translucentBackgroundColor,
                  }}
                />
                {item.imageCaption ? (
                  <Text style={{...styles.imageCaption, color: theme.foregroundColor}}>
                    {item.imageCaption}
                  </Text>
                ) : null}
              </View>
            );
          }

          const mergedText = item.runs.map(run => run.text).join(' ').trim();
          const paragraphStyle = isBulletLine(mergedText)
            ? styles.bulletText
            : styles.paragraphText;
          return (
            <View
              style={{
                ...styles.paragraphCard,
                borderColor: theme.dividerColor,
                backgroundColor: theme.translucentBackgroundColor,
              }}>
              <Text style={{...paragraphStyle, color: theme.foregroundColor}}>
                {item.runs.map((run, runIndex) => {
                  const hrefAnchor = run.href?.startsWith('#')
                    ? run.href.slice(1)
                    : null;
                  const textParts = normalizedQuery
                    ? splitHighlight(run.text, normalizedQuery)
                    : [{text: run.text, highlighted: false}];

                  return (
                    <Text
                      key={`${item.anchor}-${item.blockIndex}-${runIndex}`}
                      testID={
                        hrefAnchor
                          ? `rules-inline-link-${item.anchor}-${item.blockIndex}-${runIndex}`
                          : undefined
                      }
                      onPress={
                        hrefAnchor
                          ? () => {
                              scrollToAnchor(hrefAnchor);
                              onAnchorNavigation?.(hrefAnchor);
                            }
                          : undefined
                      }
                      style={
                        hrefAnchor
                          ? {
                              color: theme.foregroundColor,
                              ...styles.linkText,
                            }
                          : {
                              color: theme.foregroundColor,
                            }
                      }>
                      {textParts.map((part, partIndex) => (
                        <Text
                          key={`${item.anchor}-${item.blockIndex}-${runIndex}-${partIndex}`}
                          style={
                            part.highlighted
                              ? {
                                  color: theme.foregroundColor,
                                  ...styles.highlightText,
                                }
                              : {color: theme.foregroundColor}
                          }>
                          {part.text}
                        </Text>
                      ))}
                    </Text>
                  );
                })}
              </Text>
            </View>
          );
        }}
      />
    );
  },
);

export default RulesDocumentView;
